create extension if not exists pgcrypto;
create type public.store_status as enum ('pending','active','suspended','rejected');
create type public.order_status as enum ('pending','accepted','preparing','ready','out_for_delivery','delivered','cancelled');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,phone text,role text not null default 'customer' check(role in ('customer','merchant','admin','courier')),created_at timestamptz default now());
create table public.categories(id text primary key,name_ar text not null,icon text,sort_order int default 0,is_active boolean default true);
create table public.stores(id uuid primary key default gen_random_uuid(),owner_id uuid references public.profiles(id),name text not null,slug text unique not null,description text,category text references public.categories(id),phone text,area text not null,address text,governorate text not null default 'البصرة' check(governorate='البصرة'),status public.store_status not null default 'pending',delivery_mode text not null default 'store' check(delivery_mode in ('store','platform')),delivery_fee numeric(12,2) not null default 0,created_at timestamptz default now());
create table public.products(id uuid primary key default gen_random_uuid(),store_id uuid not null references public.stores(id) on delete cascade,name text not null,description text,price numeric(12,2) not null check(price>=0),unit text default 'للقطعة',stock_quantity numeric(12,2),image_url text,is_active boolean default true,created_at timestamptz default now());
create table public.orders(id uuid primary key default gen_random_uuid(),customer_id uuid references public.profiles(id),store_id uuid not null references public.stores(id),customer_name text not null,phone text not null,delivery_area text not null,delivery_address text not null,notes text,delivery_mode text not null default 'store' check(delivery_mode in ('store','platform')),delivery_fee numeric(12,2) not null default 0,subtotal numeric(12,2) not null,total_amount numeric(12,2) not null,currency text default 'IQD',status public.order_status default 'pending',created_at timestamptz default now());
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid references public.products(id),product_name text not null,quantity numeric(12,2) not null check(quantity>0),unit_price numeric(12,2) not null check(unit_price>=0));
create table public.delivery_assignments(id uuid primary key default gen_random_uuid(),order_id uuid unique not null references public.orders(id) on delete cascade,courier_id uuid references public.profiles(id),status text default 'unassigned');
create table public.reviews(id uuid primary key default gen_random_uuid(),store_id uuid not null references public.stores(id),customer_id uuid not null references public.profiles(id),rating int not null check(rating between 1 and 5),comment text,created_at timestamptz default now());
create table public.subscriptions(id uuid primary key default gen_random_uuid(),store_id uuid not null references public.stores(id),plan text default 'free',status text default 'active',starts_at timestamptz default now(),ends_at timestamptz,amount numeric(12,2) default 0);
create index stores_status_category on public.stores(status,category);
create index products_store on public.products(store_id,is_active);
create index orders_store_created on public.orders(store_id,created_at desc);
alter table public.profiles enable row level security;alter table public.categories enable row level security;alter table public.stores enable row level security;alter table public.products enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;alter table public.reviews enable row level security;alter table public.subscriptions enable row level security;
create policy "public active categories" on public.categories for select using(is_active=true);
create policy "public active stores" on public.stores for select using(status='active');
create policy "merchant own store read" on public.stores for select using(owner_id=auth.uid());
create policy "public active products" on public.products for select using(is_active=true);
create policy "profile read self" on public.profiles for select using(auth.uid()=id);
create policy "merchant store update" on public.stores for update using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy "merchant products manage" on public.products for all using(exists(select 1 from public.stores s where s.id=store_id and s.owner_id=auth.uid())) with check(exists(select 1 from public.stores s where s.id=store_id and s.owner_id=auth.uid()));
create policy "customer create orders" on public.orders for insert with check(customer_id=auth.uid() or customer_id is null);
create policy "customer own orders" on public.orders for select using(customer_id=auth.uid());
create policy "merchant own orders" on public.orders for select using(exists(select 1 from public.stores s where s.id=store_id and s.owner_id=auth.uid()));
create policy "order items read" on public.order_items for select using(exists(select 1 from public.orders o where o.id=order_id and o.customer_id=auth.uid()) or exists(select 1 from public.orders o join public.stores s on s.id=o.store_id where o.id=order_id and s.owner_id=auth.uid()));
insert into public.categories(id,name_ar,icon,sort_order) values('grocery','غذائيات','🥬',1),('fashion','ملابس وأحذية','👕',2),('beauty','عطور وتجميل','🧴',3),('tech','إلكترونيات','🎧',4),('bakery','مخابز وحلويات','🥐',5),('home','أدوات منزلية','🏠',6) on conflict do nothing;
-- قبل الإنتاج: أضف سياسات دقيقة لإنشاء order_items عبر API موثوق، والتحقق من السعر والمخزون والخادم. لا تسمح للعميل بتحديد الأسعار النهائية من المتصفح.
